#!/usr/bin/env python3
import os, sys, re, json, time, fnmatch, hashlib, difflib, unicodedata
from pathlib import Path

try:
    from data_blob import DATA
except Exception:
    # when run as __main__ from same dir, python path includes script dir
    sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
    from data_blob import DATA

VERSION = "0.1.13"
PROG = os.path.basename(sys.argv[0]) if sys.argv else "executable"
if PROG.endswith(".py"):
    PROG = PROG[:-3]
RULES = DATA["rules"]
RULE_BY_CODE = {r["code"]: r for r in RULES}
RULE_CODES = [r["code"] for r in RULES]
# alias -> code
ALIAS_TO_CODE = {}
for r in RULES:
    ALIAS_TO_CODE[r["name"].lower()] = r["code"]
    for a in r.get("aliases", []):
        ALIAS_TO_CODE[a.lower()] = r["code"]
ERROR_RULES = {"MD001","MD011","MD024","MD025","MD042","MD045","MD051","MD057","MD066","MD068"}
OPT_IN_RULES = {"MD060","MD063","MD072","MD073"}
START_TIME = time.time()

def elapsed_ms():
    return max(1, int((time.time()-START_TIME)*1000))

def resolve_rule_id(s):
    if not s: return None
    up = s.upper()
    if up in RULE_BY_CODE: return up
    low = s.lower()
    if low in ALIAS_TO_CODE: return ALIAS_TO_CODE[low]
    return None

def suggest_rule(s):
    # difflib close suggestion like original (MD999 -> MD069)
    cand = difflib.get_close_matches(s.upper(), RULE_CODES, n=1, cutoff=0.6)
    return cand[0] if cand else None

# ---------- TOML parsing (subset) ----------
class TomlError(Exception): pass

def _strip_toml_comments(s):
    out=[]; i=0; in_str=None; esc=False
    while i < len(s):
        c=s[i]
        if in_str:
            out.append(c)
            if esc: esc=False
            elif c=='\\' and in_str=='"': esc=True
            elif c==in_str: in_str=None
            i+=1; continue
        if c in ('"',"'"):
            in_str=c; out.append(c); i+=1; continue
        if c=='#':
            break
        out.append(c); i+=1
    return ''.join(out)

def _split_top(s, sep=','):
    parts=[]; depth=0; in_str=None; esc=False; cur=''
    for c in s:
        if in_str:
            cur+=c
            if esc: esc=False
            elif c=='\\' and in_str=='"': esc=True
            elif c==in_str: in_str=None
            continue
        if c in ('"',"'"): in_str=c; cur+=c; continue
        if c in '[{(': depth+=1
        if c in ']})': depth-=1
        if c==sep and depth==0:
            parts.append(cur); cur=''; continue
        cur+=c
    if cur.strip()!='' or parts: parts.append(cur)
    return parts

def _parse_toml_value(s):
    s=s.strip()
    if not s: raise TomlError("empty value")
    if s.startswith('"""') or s.startswith("'''"):
        q=s[:3]
        end=s.rfind(q,3)
        if end==-1: raise TomlError("unterminated string")
        body=s[3:end]
        if q=='"""':
            body=bytes(body,"utf-8").decode("unicode_escape") if '\\' in body else body
        return body
    if s[0]=='"' and len(s)>=2:
        # find closing
        try: return json.loads(s if s.startswith('"') and s.count('"')>=2 and _is_json_str(s) else s)
        except Exception: pass
        # manual
        return _parse_basic_string(s)
    if s[0]=="'" :
        end=s.rfind("'")
        return s[1:end]
    if s.startswith('['):
        # strip outer
        inner=s[1:-1] if s.rstrip().endswith(']') else s[1:]
        vals=[]
        for part in _split_top(inner,','):
            if part.strip()=='' : continue
            vals.append(_parse_toml_value(part))
        return vals
    if s.startswith('{'):
        inner=s[1:-1] if s.rstrip().endswith('}') else s[1:]
        d={}
        for part in _split_top(inner,','):
            if part.strip()=='' : continue
            if '=' in part:
                k,v=part.split('=',1); d[_parse_key(k)]=_parse_toml_value(v)
            elif ':' in part:
                k,v=part.split(':',1); d[_parse_key(k)]=_parse_toml_value(v)
        return d
    if s in ('true','false'): return s=='true'
    # numbers
    try:
        return int(s.replace('_',''),0) if not s.startswith('0x')==False else int(s,0)
    except Exception:
        pass
    try: return int(s.replace('_',''))
    except Exception: pass
    try: return float(s.replace('_',''))
    except Exception: pass
    return s

def _is_json_str(s):
    # json.loads works for basic string with escapes; ensure whole string consumed
    try:
        v=json.loads(s); return isinstance(v,str)
    except Exception: return False

def _parse_basic_string(s):
    # s starts with "
    i=1; out=''
    while i < len(s):
        c=s[i]
        if c=='\\' and i+1<len(s):
            n=s[i+1]
            mp={'n':'\n','t':'\t','r':'\r','\\':'\\','"':'"',"'":"'"}
            if n in mp: out+=mp[n]; i+=2; continue
            if n=='u' and i+5<len(s):
                try: out+=chr(int(s[i+2:i+6],16)); i+=6; continue
                except Exception: pass
            out+=n; i+=2; continue
        if c=='"': break
        out+=c; i+=1
    return out

def _parse_key(s):
    s=s.strip()
    if s.startswith('"') and len(s)>=2: return _parse_basic_string(s)
    if s.startswith("'") and len(s)>=2: return s[1:s.rfind("'")]
    return s

def parse_toml(text):
    # Returns nested dict; raises TomlError with rust-like message approximated by caller if needed
    root={}
    cur=root
    lines=text.splitlines()
    i=0
    while i < len(lines):
        raw=lines[i]; i+=1
        line=_strip_toml_comments(raw).strip()
        if not line: continue
        if line.startswith('['):
            if line.startswith('[['):
                raise TomlError("array of tables not supported")
            if not line.endswith(']'):
                # mimic original error info passed through
                raise TomlError(f"TOML parse error at line {i}, column {len(raw)}")
            header=line[1:-1].strip()
            parts=[_parse_key(p) for p in _split_top(header,'.') ]
            cur=root
            for p in parts:
                if p not in cur or not isinstance(cur[p], dict): cur[p]={}
                cur=cur[p]
            continue
        # key = value, value may span multiline array / string
        if '=' not in line:
            raise TomlError(f"TOML parse error at line {i}")
        keypart, valpart = line.split('=',1)
        # accumulate multiline for arrays / triple strings
        vstr=valpart.strip()
        # multiline basic string
        if vstr.startswith('"""') and vstr.count('"""')<2:
            while i < len(lines):
                vstr+='\n'+lines[i]; i+=1
                if '"""' in lines[i-1]: break
        elif vstr.startswith('['):
            depth=vstr.count('[')-vstr.count(']')
            while depth>0 and i < len(lines):
                nxt=_strip_toml_comments(lines[i]); i+=1
                vstr+='\n'+nxt
                depth+=nxt.count('[')-nxt.count(']')
        elif vstr.startswith('{'):
            depth=vstr.count('{')-vstr.count('}')
            while depth>0 and i < len(lines):
                nxt=_strip_toml_comments(lines[i]); i+=1
                vstr+='\n'+nxt
                depth+=nxt.count('{')-nxt.count('}')
        keys=[_parse_key(p) for p in _split_top(keypart.strip(),'.')]
        target=cur
        for k in keys[:-1]:
            if k not in target or not isinstance(target[k],dict): target[k]={}
            target=target[k]
        try:
            target[keys[-1]]=_parse_toml_value(vstr)
        except TomlError:
            raise
        except Exception as e:
            raise TomlError(str(e))
    return root

def toml_type_name(v):
    if isinstance(v,bool): return "boolean"
    if isinstance(v,int): return "integer"
    if isinstance(v,float): return "float"
    if isinstance(v,str): return "string"
    if isinstance(v,list): return "array"
    if isinstance(v,dict): return "table"
    return type(v).__name__

# ---------- Config ----------
def kebab(k):
    return k.replace('_','-')

def normalize_flavor(v):
    if not isinstance(v,str): return "standard"
    lv=v.lower()
    mp={"gfm":"standard","github":"standard","commonmark":"standard","standard":"standard","mkdocs":"mkdocs","mdx":"mdx","quarto":"quarto","obsidian":"obsidian"}
    return mp.get(lv, "standard")

FLAVOR_DISPLAY={"standard":"Standard","mkdocs":"MkDocs","mdx":"MDX","quarto":"Quarto","obsidian":"Obsidian"}

class Config:
    def __init__(self):
        self.defaults = json.loads(json.dumps(DATA["config_defaults"]))  # deep copy preserving order
        # effective values keyed as defaults: global, per-file-ignores, per-file-flavor, code-block-tools, MDxxx
        self.values = json.loads(json.dumps(DATA["config_defaults"]))
        # ensure per etc are dicts
        if not isinstance(self.values.get("per-file-ignores"), dict): self.values["per-file-ignores"]={}
        if not isinstance(self.values.get("per-file-flavor"), dict): self.values["per-file-flavor"]={}
        self.sources={}  # (section,key) -> "default" | "project config" | "pyproject.toml"
        self.file_path=None  # Path or None
        self.file_name=None
        self.source_label_default="default"
        self.raw={}  # raw parsed for get display (user provided normalized)
        self.user_rule={}  # code -> dict normalized kebab keys -> raw value (includes severity etc)
        self.user_global={}  # kebab -> raw
        self.global_line_length_explicit=False
        self.warnings=[]  # list strings printed as config warnings during check
        self.invalid_rule_configs={}  # code -> warning text for type mismatch repeat
        self.is_pyproject=False
    def source_for(self, section, key):
        return self.sources.get((section,key), "default")
    def get_global(self, key, default=None):
        return self.values.get("global",{}).get(key, default)
    def get_rule_cfg(self, code):
        cfg={}
        if code in self.values and isinstance(self.values[code], dict):
            cfg.update(self.values[code])
        # overlay user raw values that are valid types? We'll overlay all user keys (normalized) for rule logic if type matches roughly
        # but defaults-overlay already done during load; keep cfg from values
        # attach severity / enabled specials
        ur=self.user_rule.get(code,{})
        if "severity" in ur: cfg["severity"]=ur["severity"]
        # for opt-in, enabled already in defaults values if user set it
        return cfg
    def effective_line_length(self, code="MD013"):
        # rule specific overrides global
        ur=self.user_rule.get(code,{})
        if "line-length" in ur and isinstance(ur["line-length"], int) and not isinstance(ur["line-length"], bool):
            return ur["line-length"]
        if code=="MD013":
            # global line-length (both kebab/underscore normalized)
            if "line-length" in self.user_global and isinstance(self.user_global["line-length"], int):
                return self.user_global["line-length"]
            # also MD013 defaults value if changed via values
            v=self.values.get("MD013",{}).get("line-length",80)
            return v
        return self.values.get(code,{}).get("line-length",80)

def _is_pyproject_file(path):
    return Path(path).name=="pyproject.toml"

def load_config_file(path, explicit=False):
    cfg=Config()
    p=Path(path)
    cfg.file_path=str(p.absolute()) if False else str(Path(os.path.abspath(str(p))))
    cfg.file_name=p.name
    cfg.is_pyproject=_is_pyproject_file(p)
    # reading handled by caller for error messages
    text=p.read_text(encoding="utf-8", errors="replace")
    # parse error handling by caller
    parsed=parse_toml(text)
    cfg.raw=parsed
    source_label="pyproject.toml" if cfg.is_pyproject else "project config"
    if cfg.is_pyproject:
        tool=parsed.get("tool",{})
        rum = tool.get("rumdl",{}) if isinstance(tool,dict) else {}
        if not isinstance(rum,dict): rum={}
        _apply_pyproject(cfg, rum, source_label)
    else:
        _apply_rumdl_toml(cfg, parsed, source_label)
    return cfg

def _record_source(cfg, section, key, label):
    cfg.sources[(section,key)]=label

def _apply_global_dict(cfg, gdict, source_label):
    if not isinstance(gdict, dict): return
    for rawk, v in gdict.items():
        k=kebab(rawk)
        cfg.user_global[k]=v
        # map to values global keys if exists in defaults global
        if k in cfg.values["global"]:
            # flavor special normalization
            if k=="flavor":
                if isinstance(v,str) and normalize_flavor(v)==v.lower() or (isinstance(v,str) and v.lower() in ("gfm","github","commonmark")):
                    cfg.values["global"][k]=normalize_flavor(v)
                    _record_source(cfg,"global",k,source_label)
                elif isinstance(v,str) and v.lower() in ("standard","mkdocs","mdx","quarto","obsidian"):
                    cfg.values["global"][k]=normalize_flavor(v)
                    _record_source(cfg,"global",k,source_label)
                else:
                    # invalid: keep default, no source
                    cfg.values["global"][k]="standard"
                continue
            cfg.values["global"][k]=v
            _record_source(cfg,"global",k,source_label)
        else:
            # known global synonyms: respect_gitignore -> respect-gitignore already kebab, line-length etc already in defaults
            # unknown global keys are retained in user_global only
            pass

def _apply_rule_dict(cfg, code, rdict, source_label):
    if not isinstance(rdict, dict): return
    norm={}
    for rawk,v in rdict.items():
        k=kebab(rawk)
        norm[k]=v
    cfg.user_rule[code]=norm
    if code not in cfg.values:
        cfg.values[code]={}
    for k,v in norm.items():
        if k=="severity": continue
        # only keys present in defaults for that rule go into values, plus enabled for opt-in (already there)
        if k in DATA["config_defaults"].get(code,{}):
            cfg.values[code][k]=v
            _record_source(cfg,code,k,source_label)
        elif k=="enabled" and code in OPT_IN_RULES:
