            code=sec.upper()
            if code in RULE_BY_CODE:
                _apply_rule_dict(cfg, code, val, source_label)
            else:
                cfg.warnings.append(f"Unknown rule in {cfg.file_name}: {sec}")
        else:
            # unknown section
            cfg.warnings.append(f"Unknown rule in {cfg.file_name}: {sec}")

def _apply_pyproject(cfg, rum, source_label):
    # rum keys: global-ish at root, rule sections, per-file-ignores, etc., also optional 'global' subtable
    for rawk, v in rum.items():
        k=kebab(rawk)
