# ---------- CLI parsing ----------
class ClapExit(Exception):
    def __init__(self, code, text, to_stderr=True):
        self.code=code; self.text=text; self.to_stderr=to_stderr

def help_text(path_tuple):
    # map to DATA helps key
    if not path_tuple: key="root_"
    else: key="root_"+"_".join(path_tuple)
    txt=DATA["helps"].get(key)
    if txt is None:
        # fallback root
        txt=DATA["helps"].get("root_","")
    txt=txt.replace("Usage: executable", f"Usage: {PROG}", 1)
    return txt

def clap_error(msg, usage_tuple, tip_positional=False, tip_arg=None, possible=None):
    lines=[]
    lines.append(f"error: {msg}")
    lines.append("")
    if tip_positional and tip_arg is not None:
        lines.append(f"  tip: to pass '{tip_arg}' as a value, use '-- {tip_arg}'")
        lines.append("")
    if possible:
        lines.append(f"  [possible values: {', '.join(possible)}]")
        lines.append("")
    usage=help_text(usage_tuple).splitlines()
    usage_line=[l for l in usage if l.startswith("Usage:")]
    # For required arg errors, usage in error strips [OPTIONS]? Original: "Usage: executable import <FILE>" vs help has [OPTIONS]. Hmm handle in caller.
    if usage_line: lines.append(usage_line[0])
    else: lines.append(f"Usage: {PROG}")
    lines.append("")
    lines.append("For more information, try '--help'.")
    raise ClapExit(2, "\n".join(lines)+"\n", True)

class OptSpec:
    def __init__(self, long, short=None, value_name=None, possible=None, is_flag=False, optional_value=False):
        self.long=long; self.short=short; self.value_name=value_name; self.possible=possible; self.is_flag=is_flag; self.optional_value=optional_value

def parse_args(argv, specs, usage_tuple, positional_name=None, max_pos=None, allow_unknown_pos_as_sub=False):
    # specs dict long->OptSpec, also short map
    by_long={s.long:s for s in specs}
    by_short={s.short:s for s in specs if s.short}
    opts={}
    pos=[]
    i=0; end_opts=False
    while i < len(argv):
        arg=argv[i]
        if end_opts:
            pos.append(arg); i+=1; continue
        if arg=="--":
            end_opts=True; i+=1; continue
        if arg in ("-h","--help") and (arg=="--help" or "help" not in [s.long for s in specs] or True):
            # clap help takes precedence if present as token (unless value consumed earlier)
            raise ClapExit(0, help_text(usage_tuple), False)
        if arg.startswith("--"):
            if "=" in arg:
                name,val=arg[2:].split("=",1); has_eq=True
            else:
                name,val=arg[2:],None; has_eq=False
            spec=by_long.get(name)
            if spec is None:
                clap_error(f"unexpected argument '--{name}' found", usage_tuple, tip_positional=(positional_name is not None), tip_arg=f"--{name}")
            if spec.is_flag:
                if has_eq:
                    # clap may accept --flag=true? treat as value attempt
                    if val.lower() in ("true","false"): opts[spec.long]=val.lower()=="true"
                    else: clap_error(f"unexpected value '{val}' for '--{name}' found; no more were expected", usage_tuple)
                else:
                    opts[spec.long]=True
                i+=1; continue
            else:
                if spec.optional_value:
                    if has_eq:
                        # validate
                        if spec.possible and val not in spec.possible:
                            clap_error(f"invalid value '{val}' for '--{name} <{spec.value_name}>'", usage_tuple, possible=spec.possible)
                        opts[spec.long]=val
                    else:
                        opts[spec.long]="true"
                    i+=1; continue
                if not has_eq:
                    if i+1>=len(argv):
                        clap_error(f"a value is required for '--{name} <{spec.value_name}>' but none was supplied", usage_tuple, possible=spec.possible)
                    val=argv[i+1]; i+=2
                else: i+=1
                if spec.possible and val not in spec.possible:
                    clap_error(f"invalid value '{val}' for '--{name} <{spec.value_name}>'", usage_tuple, possible=spec.possible)
                opts[spec.long]=val
                continue
        if arg.startswith("-") and arg!="-" and len(arg)>1:
            # short cluster
            j=1; consumed_next=False
            while j < len(arg):
                ch=arg[j]
                spec=by_short.get(ch)
                if ch=="h":
                    raise ClapExit(0, help_text(usage_tuple), False)
                if ch=="V" and usage_tuple==():
                    raise ClapExit(0, f"rumdl {VERSION}\n", False)
                if spec is None:
                    clap_error(f"unexpected argument '-{ch}' found", usage_tuple, tip_positional=(positional_name is not None), tip_arg=f"-{ch}")
                if spec.is_flag:
                    opts[spec.long]=True; j+=1; continue
                else:
                    # value is rest of arg or next
                    if j+1 < len(arg):
                        val=arg[j+1:]
                        if val.startswith("="): val=val[1:]
                        j=len(arg)
                    else:
                        if i+1>=len(argv):
                            clap_error(f"a value is required for '--{spec.long} <{spec.value_name}>' but none was supplied", usage_tuple, possible=spec.possible)
                        val=argv[i+1]; consumed_next=True; j=len(arg)
                    if spec.possible and val not in spec.possible:
                        clap_error(f"invalid value '{val}' for '--{spec.long} <{spec.value_name}>'", usage_tuple, possible=spec.possible)
                    opts[spec.long]=val
            i+= (2 if consumed_next else 1); continue
        else:
            pos.append(arg); i+=1; continue
    if max_pos is not None and len(pos)>max_pos:
        extra=pos[max_pos]
        clap_error(f"unexpected argument '{extra}' found", usage_tuple, tip_positional=False)
    return opts, pos

GLOBAL_SPECS=[
    OptSpec("color", value_name="COLOR", possible=["auto","always","never"]),
    OptSpec("config", value_name="CONFIG"),
    OptSpec("no-config", is_flag=True),
    OptSpec("isolated", is_flag=True),
    OptSpec("help", short="h", is_flag=True),
    OptSpec("version", short="V", is_flag=True),
]
def global_spec_list(extra):
    # avoid duplicates by long
    seen={s.long for s in extra}
    return extra+[s for s in GLOBAL_SPECS if s.long not in seen]

