def merge_global(opts, gopts):
    for k,v in gopts.items():
        if k not in opts: opts[k]=v
    return opts

# ---------- Config command ----------
def format_toml_value(v):
    if isinstance(v,bool): return "true" if v else "false"
    if isinstance(v,str): return json.dumps(v, ensure_ascii=False)
    if isinstance(v,(int,float)): return str(v)
    if isinstance(v,list):
        if len(v)<=1:
            return "["+", ".join(format_toml_value(x) for x in v)+"]" if v else "[]"
        inner=",\n".join("    "+format_toml_value(x) for x in v)
        return "[\n"+inner+",\n]"
    if isinstance(v,dict):
        if not v: return "{}"
        return "{"+", ".join(f"{json.dumps(k)} = {format_toml_value(val)}" for k,val in v.items())+"}"
    return json.dumps(str(v))

def format_text_value(v, section=None, key=None):
    if section=="global" and key=="flavor":
        return FLAVOR_DISPLAY.get(normalize_flavor(v) if isinstance(v,str) else "standard","Standard")
    if section=="global" and key=="respect_gitignore":
        return "true" if v else "false"
    if isinstance(v,bool): return "true" if v else "false"
    if isinstance(v,str): return json.dumps(v, ensure_ascii=False)
    if isinstance(v,(int,float)): return str(v)
    if isinstance(v,list): return "["+", ".join(format_text_value(x) for x in v)+"]"
    if isinstance(v,dict):
        if not v: return "{}"
        return "{"+", ".join(f"{json.dumps(k)}: {format_text_value(val)}" for k,val in v.items())+"}"
    return str(v)

def config_object_for_output(cfg, mode):
    # mode: normal, defaults, no-defaults
    defaults=DATA["config_defaults"]
    if mode=="defaults":
        return json.loads(json.dumps(defaults))
    out={}
    out["global"]=json.loads(json.dumps(cfg.values["global"]))
    out["per-file-ignores"]=cfg.values.get("per-file-ignores",{})
    out["per-file-flavor"]=cfg.values.get("per-file-flavor",{})
    out["code-block-tools"]=cfg.values.get("code-block-tools",{})
    # rule sections only non-default (or user-provided non-default)
    for code in RULE_CODES:
        if code not in defaults: continue
        defv=defaults[code]
        curv=cfg.values.get(code,{})
        diff={}
        for k,dval in defv.items():
            if k in curv and curv[k]!=dval:
                diff[k]=curv[k]
        if diff: out[code]=diff
    if mode=="no-defaults":
        # same as normal for json/toml except ??? observed same global full
        pass
    return out

def toml_dump_config(obj):
    lines=[]
    # global first, then per..., code..., then rules in order given
    order=[]
    for k in ["global","per-file-ignores","per-file-flavor","code-block-tools"]:
        if k in obj: order.append(k)
    for k in obj.keys():
        if k not in order: order.append(k)
    for sec in order:
        val=obj[sec]
        if sec=="per-file-ignores":
            lines.append("[per-file-ignores]")
            for k,v in val.items():
                lines.append(f"{json.dumps(k)} = {format_toml_value(v)}")
            lines.append("")
            continue
        if sec=="per-file-flavor":
            lines.append("[per-file-flavor]")
            for k,v in val.items():
                lines.append(f"{json.dumps(k)} = {format_toml_value(v)}")
            lines.append("")
            continue
        if sec=="code-block-tools":
            lines.append("[code-block-tools]")
            for k,v in val.items():
                if isinstance(v,dict): continue
                lines.append(f"{k} = {format_toml_value(v)}")
            lines.append("")
            lines.append("[code-block-tools.languages]")
            lang=val.get("languages",{})
            for k,v in lang.items():
                lines.append(f"{k} = {format_toml_value(v)}")
            lines.append("")
            lines.append("[code-block-tools.language-aliases]")
            la=val.get("language-aliases",{})
            for k,v in la.items():
                lines.append(f"{json.dumps(k) if not re.match(r'^[A-Za-z0-9_-]+$',k) else k} = {format_toml_value(v)}")
            lines.append("")
            lines.append("[code-block-tools.tools]")
            tools=val.get("tools",{})
            for k,v in tools.items():
                lines.append(f"{k} = {format_toml_value(v)}")
            lines.append("")
            continue
        # normal table
        lines.append(f"[{sec}]")
        subtables=[]
        for k,v in val.items():
            if isinstance(v,dict):
                subtables.append((k,v)); continue
            lines.append(f"{k} = {format_toml_value(v)}")
        lines.append("")
        for k,v in subtables:
            lines.append(f"[{sec}.{k}]")
            for kk,vv in v.items():
                lines.append(f"{kk} = {format_toml_value(vv)}")
            lines.append("")
    # remove possible trailing duplicate blank? Original ends with single newline after last blank line? Check: toml output ends with "\n\n"? We'll normalize to end with "\n" if last line blank one
    txt="\n".join(lines)
    if not txt.endswith("\n"): txt+="\n"
    return txt

def do_config(opts, pos, gopts):
    opts=merge_global(opts, gopts)
    # subcommand handling crude: pos may contain get/file
    # Caller splits subcommand before
    return None

