def visual_width(s):
    w=0
    for ch in s:
        if ch=='\t': w+=4; continue
        if unicodedata.combining(ch): continue
        if unicodedata.east_asian_width(ch) in ('W','F'): w+=2; continue
        # emoji presentation etc approx: many are W already
        w+=1
    return w

