@rulefn("MD029")
def r029(ctx, issues):
    # quirk: only if unordered present somewhere
    if not any(not it.ordered for it in ctx.list_items): return
    cfg=ctx.cfg_for("MD029"); style=cfg.get("style","one-or-ordered")
    # group ordered items contiguous by line proximity and same indent, separated by blank/text
    groups=[]; cur=[]
    for it in ctx.list_items:
        if not it.ordered: 
            if cur: groups.append(cur); cur=[]
            continue
        if cur and (it.line_idx != cur[-1].line_idx+1 and not (it.line_idx==cur[-1].line_idx+2 and ctx.lines[cur[-1].line_idx+1].strip()=="" )):
            # could be continuation / blank between items in loose list - if blank line then next item still same list if same indent? markdown loose lists allow blanks. But grouping by indent: if previous group ended because blank, we still append if indent same and no intervening non-list content besides blank
            # check intervening content
            between=[ctx.lines[x] for x in range(cur[-1].line_idx+1, it.line_idx)]
            if any(x.strip() and not re.match(r'^\s+', x) for x in between):
                groups.append(cur); cur=[]
        if cur and it.indent!=cur[-1].indent:
            groups.append(cur); cur=[]
        cur.append(it)
    if cur: groups.append(cur)
    for grp in groups:
        if len(grp)<2: 
            # single item with style ordered and starting not 1? check?
            continue
        nums=[it.num for it in grp]
        # determine effective style
        configured = style not in ("one-or-ordered","consistent")
        eff=style
        if style=="one-or-ordered":
            # infer: if all ones -> one ; elif sequential from first -> ordered ; else ordered (flag mismatches)
            if all(n==1 for n in nums): eff="one"
            elif all(nums[i]==nums[0]+i for i in range(len(nums))): eff="ordered"
            else: eff="ordered"
        elif style=="consistent":
            # document-wide: use first group's style - approximate as one-or-ordered per group for now
            if all(n==1 for n in nums): eff="one"
            else: eff="ordered"
        elif style=="one-one": eff="one"
        # expected per index
        for idx,it in enumerate(grp):
            if eff=="one": exp=1
            elif eff=="zero" or eff=="ordered0": exp=idx  # 0-based if first is 0?
            elif eff=="ordered": exp=nums[0]+idx if style in ("one-or-ordered","consistent") else 1+idx
            else: exp=it.num
            if eff=="ordered" and configured and style=="ordered": exp=1+idx
            if eff=="ordered0": exp=idx
            if it.num!=exp:
                if configured:
                    msg=f"Ordered list item number {it.num} does not match configured style '{style}' (expected {exp})"
                else:
                    msg=f"Ordered list item number {it.num} does not match list style '{eff}' (expected {exp})"
                # fix replace marker digits
                start=it.indent; end=it.indent+len(str(it.num))
                fix=ctx.fix_range(it.line_idx,start,end,str(exp))
                ctx.add(issues,it.line_idx,1,"MD029",msg,True,fix)

