@rulefn("MD032")
def r032(ctx, issues):
    cfg=ctx.cfg_for("MD032"); allow_lazy=cfg.get("allow-lazy-continuation",True)
    items=ctx.list_items
    if not items: return
    # find list blocks: start = first item that follows non-blank non-list line, end = last item in contiguous group
    # Group items where lines between are list items or indented continuation or blank-internal? Simple: iterate items sorted, group if next item line - prev item line <=? and intervening lines are blank/ indented / continuation
    groups=[]; cur=[items[0]]
    for it in items[1:]:
        prev=cur[-1]
        between_lines=list(range(prev.line_idx+1, it.line_idx))
        # if there's a non-blank line that is not indented and not a list item => group break (new list)
        breaks=False
        for bi in between_lines:
            if ctx.lines[bi].strip()=="": continue
            if ctx.lines[bi].startswith((" ","\t")): continue
            # lazy continuation line at col0 is part of previous item if allow_lazy
            if allow_lazy: continue
            breaks=True
        if breaks: groups.append(cur); cur=[it]
        else: cur.append(it)
    if cur: groups.append(cur)
    for grp in groups:
        first=grp[0]; last=grp[-1]
        # preceded
        if first.line_idx>0:
            # if prev line is frontmatter end? skip
            if not ctx.is_front(first.line_idx-1) and ctx.lines[first.line_idx-1].strip()!="":
                # prev could be a heading? That's also? MD032 expects blank before list even after heading? test: yes lists should be surrounded
                # But if prev is another list item (different group) skip
                if not any(x.line_idx==first.line_idx-1 for x in items):
                    fix=ctx.fix_insert(first.line_idx,0,"\n")
                    ctx.add(issues,first.line_idx,1,"MD032","List should be preceded by blank line",True,fix,end_line=first.line_idx+1,end_col=2)
        # followed: need determine end of list including continuation lines
        # Find last line belonging to list: scan forward from last item while lines are indented/blank followed by indented...
        end_idx=last.line_idx
        j=end_idx+1
        while j < len(ctx.lines):
            if ctx.lines[j].strip()=="":
                # blank internal if next is indented continuation or item (but group would include) - break here, this blank counts as following blank
                break
            if ctx.lines[j].startswith((" ","\t")):
                end_idx=j; j+=1; continue
            if allow_lazy and j==last.line_idx+1:
                # single lazy continuation line directly after last item at col0 is part of item
                end_idx=j; j+=1; continue
            break
        if end_idx+1 < len(ctx.lines):
            nxt=end_idx+1
            if ctx.lines[nxt].strip()!="":
                # if next is list item (other group) skip
                if not any(x.line_idx==nxt for x in items):
                    fix=ctx.fix_insert(nxt,0,"\n")
                    # Original message position? Harvest MD032 only before issue. Probe after case later: issue at last list line? Let's place at last item line ??? Need initial guess: line of list end (?) Original in README check: MD032 at line30 (list start) for preceded. For after, likely at last item line
                    ctx.add(issues,last.line_idx,1,"MD032","List should be followed by blank line",True,fix)

