@rulefn("MD034")
def r034(ctx, issues):
    url_pat=re.compile(r'https?://[^\s<>\[\]()]+|ftp://[^\s<>\[\]()]+|www\.[^\s<>\[\]()]+')
    email_pat=re.compile(r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}\b')
    xmpp_pat=re.compile(r'xmpp:[^\s<>\[\]()]+')
    for i,l in enumerate(ctx.lines):
        if ctx.is_code(i) or ctx.is_front(i) or ctx.is_fence_line(i): continue
        masked=list(mask_code_spans(l))
        # mask links: inline link destinations and text in brackets, autolinks <...>, reference definitions, html tags
        s=''.join(masked)
        # mask [text](url) and [text][ref] entirely
        for m in re.finditer(r'!?\[[^\]]*\]\([^)]*\)', s): 
            for k in range(m.start(),m.end()): masked[k]=' '
        for m in re.finditer(r'!?\[[^\]]*\]\[[^\]]*\]', ''.join(masked)):
            for k in range(m.start(),m.end()): masked[k]=' '
        s=''.join(masked)
        for m in re.finditer(r'<[^>]+>', s):
            for k in range(m.start(),m.end()): masked[k]=' '
        s=''.join(masked)
        if re.match(r'^\s*\[[^\]]+\]:', s): continue
        # find urls/emails in order
        found=[]
        for m in xmpp_pat.finditer(s): found.append((m.start(),m.end(),m.group(0),"URL"))
        for m in url_pat.finditer(s): found.append((m.start(),m.end(),m.group(0),"URL"))
        for m in email_pat.finditer(s):
            # avoid email part of URL/xmpp: check overlap
            if any(not (m.end()<=a or m.start()>=b) for a,b,_,_ in found): continue
            # avoid emails inside link text (?) already masked links
            found.append((m.start(),m.end(),m.group(0),"Email address"))
        found.sort()
        for a,b,txt,kind in found:
            # trim trailing punctuation .,;:!? and ) common
            while txt and txt[-1] in '.,;:!?': txt=txt[:-1]; b-=1
            if kind=="URL":
                msg=f"URL without angle brackets or link formatting: '{txt}'"
            else:
                msg=f"Email address without angle brackets or link formatting: '{txt}'"
            fix=ctx.fix_range(i,a,b,f"<{txt}>")
            ctx.add(issues,i,a+1,"MD034",msg,True,fix,end_line=i+1,end_col=b+1)

