def github_anchor(text, anchor_style="github"):
    # slugify heading
    t=text.strip().lower()
    # remove markdown formatting links etc crude
    t=re.sub(r'\[([^\]]+)\]\([^)]*\)', r'\1', t)
    t=re.sub(r'<[^>]+>', '', t)
    t=t.replace('`','')
    # GitHub: remove punctuation except - and _, spaces to -
    t=re.sub(r'[^\w\- ]', '', t, flags=re.UNICODE)
    t=t.replace(' ', '-')
    return t

