def apply_heading_capitalization(txt, style, lowercase_words, ignore, preserve):
    words=txt.split(' ')
    if style=="title_case":
        out=[]
        for idx,w in enumerate(words):
            # preserve hyphenated? handle each part
            parts=w.split('-')
            newparts=[]
            for pidx,p in enumerate(parts):
                low=p.lower()
                # strip punctuation for check
                core=re.sub(r'[^A-Za-z]', '', p)
                if core.lower() in ignore: newparts.append(p); continue
                is_first_or_last=(idx==0 and pidx==0) or (idx==len(words)-1 and pidx==len(parts)-1)
                if core.lower() in lowercase_words and not is_first_or_last:
                    newparts.append(low if p.islower() or True else p)
                    # lowercase whole part preserving punctuation? Simplify: lowercase letters
                    newparts[-1]=re.sub(r'[A-Za-z]+', lambda m: m.group(0).lower(), p)
                else:
                    if preserve and any(c.isupper() for c in p[1:]) if len(p)>1 else False:
