                        newparts.append(p)
                    else:
                        # capitalize first letter, rest lower unless preserve?
                        newparts.append(re.sub(r'[A-Za-z]+', lambda m: m.group(0)[:1].upper()+m.group(0)[1:].lower(), p, count=1))
            out.append('-'.join(newparts))
        return ' '.join(out)
