def make_diff(display, orig, fixed):
    import difflib
    orig_lines=orig.splitlines(keepends=True)
    fixed_lines=fixed.splitlines(keepends=True)
    # difflib requires lines with endings; if last line no nl, it still works but output markers missing
    diff=list(difflib.unified_diff(orig_lines, fixed_lines, fromfile=display, tofile=f"{display} (fixed)", n=3, lineterm=""))
    # difflib first two lines have lineterm handling; reconstruct:
    out=[]
    out.append(f"--- {display}")
    out.append(f"+++ {display} (fixed)")
    # skip first 2 from difflib
    for line in diff[2:]:
        if line.endswith("\n"): out.append(line[:-1])
        else: out.append(line)
    return "\n".join(out)+"\n"

