            out_content=fixed_norm.replace("\n","\r\n") if had_crlf else fixed_norm
            sys.stdout.write(out_content); sys.stdout.flush()
            fixed_count=sum(1 for i in initial if i.fixable)
            # remaining diagnostics: format depends
            if fmt=="json":
                # prints json of remaining to ??? It previously appeared after content in combined; will print to stdout as json array
                print_out(json.dumps([i.to_json() for i in remaining], indent=2)+"\n")
            elif fmt in ("json-lines","github","gitlab","pylint","azure","sarif","junit","grouped","concise"):
