            if is_fmt: return 0
            return fail_exit_code(remaining, opts, is_fmt_cmd=False)
    # normal stdin check (including check --diff stdin)
    issues,_=lint_content(content, cfg, display, disk_for_links, opts, enabled)
    if opts.get("silent"):
        return fail_exit_code(issues, opts, is_fmt_cmd=is_fmt)
    if fmt=="json":
        print_out(json.dumps([i.to_json() for i in issues], indent=2)+"\n"); return fail_exit_code(issues, opts, is_fmt_cmd=is_fmt)
    if fmt in ("gitlab","sarif","junit"):
        dummy=[(display,display)]; output_results([issues], dummy, opts, cfg, {"format":fmt}, "stdout"); return fail_exit_code(issues, opts, is_fmt_cmd=is_fmt)
    # text-like to stderr
    use_color=opts.get("color","auto")=="always"
    if fmt=="grouped" or fmt=="json-lines" or fmt in ("github","pylint","azure"):
        dummy=[(display,display)]
        # These formats in stdin normal likely go to stdout? But text goes stderr; for simplicity use stderr for json-lines/github etc as diagnostics,
        # output_results writes summary to same stream - stdin summary is custom, so suppress by quiet trick: temporarily set quiet?
        # We'll manually print:
        if fmt=="grouped":
            from collections import defaultdict
            if issues:
                sys.stderr.write(f"{display}:\n")
                by={}
                for i in issues: by.setdefault(i.rule,[]).append(i)
                for rule in sorted(by):
                    sys.stderr.write(f"  {rule}:\n")
                    for i in by[rule]: sys.stderr.write(f"    {i.line}:{i.column} {i.message}{' (fixable)' if i.fixable else ''}\n")
        elif fmt=="json-lines":
            for i in issues: sys.stderr.write(json.dumps({"file":i.file,"line":i.line,"column":i.column,"rule":i.rule,"message":i.message,"severity":i.severity,"fixable":i.fixable}, separators=(',',':'))+"\n")
        elif fmt=="github":
            lm={"error":"error","warning":"warning","info":"notice"}
            for i in issues:
                s=f"::{lm.get(i.severity,'warning')} file={i.file},line={i.line},col={i.column}"
                if i.end_line is not None: s+=f",endLine={i.end_line},endColumn={i.end_column}"
                s+=f",title={i.rule}::{i.message}"; sys.stderr.write(s+"\n")
        elif fmt=="pylint":
            for i in issues: sys.stderr.write(f"{i.file}:{i.line}:{i.column}: [C{i.rule}] {i.message}\n")
        elif fmt=="azure":
            for i in issues: sys.stderr.write(f"##vso[task.logissue type={'error' if i.severity=='error' else 'warning'};sourcepath={i.file};linenumber={i.line};columnnumber={i.column};code={i.rule}]{i.message}\n")
    else:
        for i in issues:
            sys.stderr.write(issue_text_line(i, concise=(fmt=="concise"), color=use_color)+"\n")
    if not opts.get("quiet"):
        sys.stderr.write("\n") if issues else None
        if issues: sys.stderr.write(f"Found {len(issues)} issue(s) in {display}\n")
        else: sys.stderr.write(f"No issues found in {display}\n")
    return fail_exit_code(issues, opts, is_fmt_cmd=is_fmt)

