import subprocess, tempfile, pathlib, os, shutil, re
ORIG="/workspace/executable"; OURS="/tmp/ourbin/executable"
def norm(s): return re.sub(r"\(\d+ms\)","X",s)
def run_scenario(exe, scenario):
  with tempfile.TemporaryDirectory() as td:
    # scenario returns (args, setup func?) We'll implement inline based on name
    if scenario=="init":
      p=subprocess.run([exe,"init"],cwd=td,capture_output=True,text=True); return p.returncode,p.stdout,p.stderr,pathlib.Path(td,".rumdl.toml").read_text() if pathlib.Path(td,".rumdl.toml").exists() else ""
    if scenario=="init_py":
      p=subprocess.run([exe,"init","--pyproject"],cwd=td,capture_output=True,text=True); return p.returncode,p.stdout,p.stderr,pathlib.Path(td,"pyproject.toml").read_text() if pathlib.Path(td,"pyproject.toml").exists() else ""
    if scenario=="init_twice":
      subprocess.run([exe,"init"],cwd=td,capture_output=True,text=True); p=subprocess.run([exe,"init"],cwd=td,capture_output=True,text=True); return p.returncode,p.stdout,p.stderr,""
    if scenario=="init_py_existing_yes":
      pathlib.Path(td,"pyproject.toml").write_text('[project]\nname="x"\n'); p=subprocess.run([exe,"init","--pyproject"],cwd=td,capture_output=True,text=True,input="y\n"); return p.returncode,p.stdout,p.stderr,pathlib.Path(td,"pyproject.toml").read_text()
    if scenario=="init_py_existing_no":
      pathlib.Path(td,"pyproject.toml").write_text('[project]\nname="x"\n'); p=subprocess.run([exe,"init","--pyproject"],cwd=td,capture_output=True,text=True,input="n\n"); return p.returncode,p.stdout,p.stderr,pathlib.Path(td,"pyproject.toml").read_text()
    if scenario=="schema_gen_check":
      p1=subprocess.run([exe,"schema","generate"],cwd=td,capture_output=True,text=True); f=pathlib.Path(td,"rumdl.schema.json").read_bytes() if pathlib.Path(td,"rumdl.schema.json").exists() else b""; p2=subprocess.run([exe,"schema","check"],cwd=td,capture_output=True,text=True)
      # normalize abs path
      return (p1.returncode,p1.stdout.replace(td,"TD"),p1.stderr.replace(td,"TD")), (p2.returncode,p2.stdout.replace(td,"TD"),p2.stderr.replace(td,"TD")), f
    if scenario=="schema_check_missing":
      p=subprocess.run([exe,"schema","check"],cwd=td,capture_output=True,text=True); return p.returncode,p.stdout.replace(td,"TD"),p.stderr.replace(td,"TD"),""
    if scenario=="import_json":
      pathlib.Path(td,"ml.json").write_text('{\n  "default": true,\n  "MD013": { "line_length": 100 },\n  "MD033": false,\n  "MD041": false\n}\n'); p=subprocess.run([exe,"import","ml.json"],cwd=td,capture_output=True,text=True); return p.returncode,p.stdout,p.stderr,pathlib.Path(td,".rumdl.toml").read_text() if pathlib.Path(td,".rumdl.toml").exists() else ""
    if scenario=="import_json_dry":
      pathlib.Path(td,"ml.json").write_text('{\n  "default": true,\n  "MD013": { "line_length": 100 },\n  "MD033": false,\n  "MD041": false\n}\n'); p=subprocess.run([exe,"import","ml.json","--dry-run"],cwd=td,capture_output=True,text=True); return p.returncode,p.stdout,p.stderr,""
    if scenario=="import_json_fmt":
      pathlib.Path(td,"ml.json").write_text('{"MD013": {"line_length": 100}, "MD033": false}\n'); p=subprocess.run([exe,"import","ml.json","--format","json","--dry-run"],cwd=td,capture_output=True,text=True); return p.returncode,p.stdout,p.stderr,""
    if scenario=="import_yaml":
      pathlib.Path(td,"ml.yaml").write_text('MD013:\n  line_length: 120\nMD003:\n  style: atx\n'); p=subprocess.run([exe,"import","ml.yaml","--dry-run"],cwd=td,capture_output=True,text=True); return p.returncode,p.stdout,p.stderr,""
    if scenario=="import_missing":
      p=subprocess.run([exe,"import","nope.json"],cwd=td,capture_output=True,text=True); return p.returncode,p.stdout,p.stderr,""
    if scenario=="import_bad":
      pathlib.Path(td,"bad.json").write_text('not json'); p=subprocess.run([exe,"import","bad.json","--dry-run"],cwd=td,capture_output=True,text=True); return p.returncode,p.stdout,p.stderr,""
    if scenario=="clean_empty":
      p=subprocess.run([exe,"clean"],cwd=td,capture_output=True,text=True); return p.returncode,p.stdout,p.stderr,""
scenarios=["init","init_py","init_twice","init_py_existing_yes","init_py_existing_no","schema_gen_check","schema_check_missing","import_json","import_json_dry","import_json_fmt","import_yaml","import_missing","import_bad","clean_empty"]
for sc in scenarios:
 ro=run_scenario(ORIG,sc); ru=run_scenario(OURS,sc)
 print(sc, "OK" if ro==ru else "FAIL")
 if ro!=ru: print(" orig",ro); print(" ours",ru)
