@rulefn("MD043")
def r043(ctx, issues):
    cfg=ctx.cfg_for("MD043"); required=cfg.get("headings",[]); match_case=cfg.get("match-case",False)
    if not isinstance(required,list) or not required: return
    actual=ctx.headings
    # parse patterns
    pats=[]
    for req in required:
        if not isinstance(req,str): continue
        if req in ("*","+","?"): pats.append((req,None,None))
        else:
            m=re.match(r'^(#{1,6})\s+(.*)$', req)
            if m: pats.append(("lit",len(m.group(1)),m.group(2)))
            else: pats.append(("lit",None,req))
    def text_eq(a,b): return a==b if match_case else a.lower()==b.lower()
    # recursive matcher
    from functools import lru_cache
    # Use iterative DP via recursion on indices (actual as tuple indexes)
    import sys as _sys; _sys.setrecursionlimit(10000)
    def matches(pi, ai):
        if pi>=len(pats): return ai>=len(actual)
        kind, lvl, txt = pats[pi]
        if kind=="*":
            for k in range(ai, len(actual)+1):
                if matches(pi+1,k): return True
            return False
        if kind=="+":
            for k in range(ai+1, len(actual)+1):
                if matches(pi+1,k): return True
            return False
        if kind=="?":
            return ai < len(actual) and matches(pi+1, ai+1)
        # lit
        if ai>=len(actual): return False
        h=actual[ai]
        if lvl is not None and h.level!=lvl: return False
        if not text_eq(h.text, txt): return False
        return matches(pi+1, ai+1)
    if matches(0,0): return
    for h in actual:
        ctx.add(issues,h.line_idx,1,"MD043","Heading structure does not match the required structure",False,None)

