old='''    remaining,_=lint_content(cur, cfg, display, disk_path, opts, enabled_global)
    return cur, initial, remaining, nested_changed'''
new='''    # code-block-tools formatting
    try:
        cbt=cbt_settings(cfg)
        if cbt.get("enabled"):
            import subprocess, shutil
            _iss2, ctx3 = lint_content(cur, cfg, display, disk_path, opts, enabled_global)
            lines=cur.split("\\n")
            timeout_ms=cbt.get("timeout",30000); timeout_s=(timeout_ms/1000 if isinstance(timeout_ms,(int,float)) and timeout_ms else 30)
            stop=False
            for blk in reversed(list(ctx3.fence_blocks)):
                if stop: break
                raw_lang=blk.get("lang",""); 
                if not raw_lang: continue
                resolved=resolve_cbt_lang(raw_lang,cfg); lcfg=cbt_language_config(cfg,resolved,raw_lang)
                fmt_tools=lcfg.get("format",[]) if isinstance(lcfg,dict) else []
                if not isinstance(fmt_tools,list) or not fmt_tools: continue
                start=blk["start"]; end=blk.get("end")
                if end is None or end<=start: continue
                ind=blk.get("indent",0); inner=lines[start+1:end]
                content="\\n".join([(x[ind:] if ind and x.startswith(" "*ind) else x) for x in inner])+"\\n" if inner else ""
                for tool_id in fmt_tools:
                    tool_id=str(tool_id)
                    if tool_id=="rumdl": continue
                    cmd=cbt_tool_command(tool_id,cfg,resolved); binary=cmd[0] if cmd else tool_id
                    missing_mode=lcfg.get("on-missing-tool-binary", cbt.get("on-missing-tool-binary","ignore")) if isinstance(lcfg,dict) else cbt.get("on-missing-tool-binary","ignore")
                    if not cmd or shutil.which(binary) is None:
                        if missing_mode=="fail": sys.stderr.write(f"Warning: Tool binary '{binary}' not found in PATH for language '{resolved}' at line {start+1}\\n")
                        elif missing_mode=="fail-fast": sys.stderr.write(f"Warning: Code block tool formatting failed: Tool '{binary}' binary not found for language '{resolved}'\\n"); stop=True; break
                        continue
                    try: proc=subprocess.run(cmd, input=content, capture_output=True, text=True, timeout=timeout_s)
                    except Exception as e: proc=None
                    if proc is None: continue
                    if proc.returncode!=0:
                        onerr=lcfg.get("on-error", cbt.get("on-error","fail")) if isinstance(lcfg,dict) else cbt.get("on-error","fail")
                        if onerr!="skip":
                            err=(proc.stderr or proc.stdout or "").strip().splitlines()
                            msg=err[0] if err else ""
                            sys.stderr.write(f"Warning: Code block tool formatting failed: Tool '{binary}' failed: Exit code {proc.returncode}: {msg}\\n")
                        continue
                    if proc.stdout: content=proc.stdout
                if content:
                    fl=content.split("\\n")
                    if content.endswith("\\n"): fl=fl[:-1]
                    if ind: fl=[(" "*ind+x if x.strip() else x) for x in fl]
                    lines[start+1:end]=fl
            cur="\\n".join(lines)
    except Exception:
        if os.environ.get("RUMDL_DEBUG"): raise
    remaining,_=lint_content(cur, cfg, display, disk_path, opts, enabled_global)
    return cur, initial, remaining, nested_changed'''
